/**  One reply. The tag `kind` selects the payload shape under `value`. */
export type Response = Response_Serialize | Response_Deserialize;

/**  One reply. The tag `kind` selects the payload shape under `value`. */
export type Response_Deserialize = { kind: "state"; value: AppState_Deserialize } | { kind: "profiles"; value: Profile[] } | { kind: "text"; value: string } | { kind: "ports"; value: number[] } | { kind: "assets"; value: string[] } | { kind: "capabilities"; value: Capabilities } | { kind: "apps"; value: AppInfo_Deserialize[] } | { kind: "status"; value: ServiceState_Deserialize } | { kind: "wsInfo"; value: WsInfo | null } | 
/**  Per-profile core resolutions, in the request's profile order. */
{ kind: "coreResolutions"; value: CoreResolution[] } | 
/**  Profile ids, in stored order. */
{ kind: "profileIds"; value: string[] } | 
/**  Two local listeners on one port, or `null` when the ports are fine. */
{ kind: "portCollision"; value: PortCollision | null } | 
/**  Latency in ms (tcp-ping and real-ping); `null` when there is no result. */
{ kind: "ping"; value: number | null } | { kind: "probe"; value: ConnectionProbe } | 
/**  Throughput in bytes/sec; `null` when there is no result. */
{ kind: "speed"; value: number | null } | 
/**  A bare acknowledgement (`{ok: true}` / no body in the old protocol). */
({ kind: "ok" }) & { value?: never } | { kind: "requestIdentity"; value: ResolvedIdentity } | { kind: "importInput"; value: ResolvedImport_Deserialize } | { kind: "backupRestored"; value: BackupRestored_Deserialize };

/**  One reply. The tag `kind` selects the payload shape under `value`. */
export type Response_Serialize = { kind: "state"; value: AppState_Serialize } | { kind: "profiles"; value: Profile[] } | { kind: "text"; value: string } | { kind: "ports"; value: number[] } | { kind: "assets"; value: string[] } | { kind: "capabilities"; value: Capabilities } | { kind: "apps"; value: AppInfo_Serialize[] } | { kind: "status"; value: ServiceState_Serialize } | { kind: "wsInfo"; value: WsInfo | null } | 
/**  Per-profile core resolutions, in the request's profile order. */
{ kind: "coreResolutions"; value: CoreResolution[] } | 
/**  Profile ids, in stored order. */
{ kind: "profileIds"; value: string[] } | 
/**  Two local listeners on one port, or `null` when the ports are fine. */
{ kind: "portCollision"; value: PortCollision | null } | 
/**  Latency in ms (tcp-ping and real-ping); `null` when there is no result. */
{ kind: "ping"; value: number | null } | { kind: "probe"; value: ConnectionProbe } | 
/**  Throughput in bytes/sec; `null` when there is no result. */
{ kind: "speed"; value: number | null } | 
/**  A bare acknowledgement (`{ok: true}` / no body in the old protocol). */
({ kind: "ok" }) & { value?: never } | { kind: "requestIdentity"; value: ResolvedIdentity } | { kind: "importInput"; value: ResolvedImport_Serialize } | { kind: "backupRestored"; value: BackupRestored_Serialize };

/**  Which blocks, in what order, a set of profiles runs with. */
export type Route = {
	id: string,
	name: string,
	/**  A switched-off route lets its profiles fall back to the default route. */
	enabled?: boolean,
	/**
	 *  Profile ids this route applies to. On the default route: profiles pinned
	 *  to it against their group's route.
	 */
	profiles?: string[],
	/**
	 *  Group ids this route applies to (every profile in them, unless a route
	 *  lists the profile itself). Empty on the default route.
	 */
	groups?: string[],
	blocks?: RouteBlockRef[],
	/**
	 *  Where traffic no rule matched goes: `proxy`, `direct`, `block` or a
	 *  profile id.
	 */
	finalOutbound?: string,
	/**  The subscription whose provider routing this route was imported from. */
	sourceSubId?: string | null,
};

/**
 *  One block's place in a route. Turning it off keeps it in place (and in
 *  other routes) while this route skips its rules.
 */
export type RouteBlockRef = {
	blockId: string,
	enabled?: boolean,
};

